"use client"

import { useState, useEffect } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Input } from "@/components/ui/input"
import { Search, Mail, UserCheck, Users, BookOpen, Loader2, Phone } from "lucide-react"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { instituteService } from "@/lib/institute-service"

interface Trainer {
  id: string
  name: string
  email: string
  phone: string | null
  status: string
  createdAt: string
  activeCourses: number
}

export default function InstituteStaff() {
  const [trainers, setTrainers] = useState<Trainer[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [searchTerm, setSearchTerm] = useState("")

  const loadTrainers = () => {
    setLoading(true)
    setError(null)
    instituteService.getStaff()
      .then((data) => setTrainers(data as Trainer[]))
      .catch(() => setError("فشل تحميل بيانات المدربين"))
      .finally(() => setLoading(false))
  }

  useEffect(() => { loadTrainers() }, [])

  const filtered = trainers.filter(t =>
    t.name.includes(searchTerm) ||
    t.email.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const activeCount = trainers.filter(t => t.status === "active").length
  const totalCourses = trainers.reduce((sum, t) => sum + (t.activeCourses ?? 0), 0)

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">إدارة الطاقم</h1>
        <p className="text-gray-600 dark:text-gray-400 mt-2">عرض ومتابعة مدربي المعهد</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">إجمالي المدربين</CardTitle>
            <Users className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{loading ? "—" : trainers.length}</div>
            <p className="text-xs text-muted-foreground">مدرب مسجّل</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">المدربون النشطون</CardTitle>
            <UserCheck className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{loading ? "—" : activeCount}</div>
            <p className="text-xs text-muted-foreground">مدرب نشط حالياً</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">الدورات النشطة</CardTitle>
            <BookOpen className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{loading ? "—" : totalCourses}</div>
            <p className="text-xs text-muted-foreground">دورة مفتوحة</p>
          </CardContent>
        </Card>
      </div>

      {/* Table */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between flex-wrap gap-4">
            <div className="flex items-center gap-3">
              <CardTitle>قائمة المدربين</CardTitle>
              {!loading && (
                <Badge variant="secondary" className="font-mono">
                  {filtered.length} مدرب
                </Badge>
              )}
            </div>
            <div className="relative w-64">
              <Search className="absolute right-3 top-3 h-4 w-4 text-gray-400" />
              <Input
                placeholder="بحث بالاسم أو البريد..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pr-10"
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-16 text-gray-400">
              <Loader2 className="h-6 w-6 animate-spin ml-2" />
              <span>جاري تحميل المدربين...</span>
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center py-16 text-red-500 gap-2">
              <span>{error}</span>
              <Button variant="outline" size="sm" onClick={loadTrainers}>
                إعادة المحاولة
              </Button>
            </div>
          ) : filtered.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-gray-400 gap-3">
              <Users className="h-10 w-10" />
              <p>{searchTerm ? "لا توجد نتائج للبحث" : "لا يوجد مدربون مسجلون حتى الآن"}</p>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>المدرب</TableHead>
                  <TableHead>معلومات الاتصال</TableHead>
                  <TableHead>الدورات النشطة</TableHead>
                  <TableHead>الحالة</TableHead>
                  <TableHead>تاريخ الانضمام</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((trainer) => (
                  <TableRow key={trainer.id}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar>
                          <AvatarFallback>{trainer.name.charAt(0)}</AvatarFallback>
                        </Avatar>
                        <div>
                          <p className="font-medium">{trainer.name}</p>
                          <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300 text-xs mt-0.5">
                            مدرب
                          </Badge>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col gap-1 text-sm text-gray-600 dark:text-gray-400">
                        <div className="flex items-center gap-2">
                          <Mail className="h-3 w-3" />
                          {trainer.email}
                        </div>
                        {trainer.phone && (
                          <div className="flex items-center gap-2">
                            <Phone className="h-3 w-3" />
                            {trainer.phone}
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="secondary">
                        {trainer.activeCourses ?? 0} دورات
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge
                        className={
                          trainer.status === "active"
                            ? "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300"
                            : "bg-gray-100 text-gray-600"
                        }
                      >
                        {trainer.status === "active" ? "نشط" : "غير نشط"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-sm text-gray-600 dark:text-gray-400">
                      {trainer.createdAt
                        ? new Date(trainer.createdAt).toLocaleDateString("ar-SA")
                        : "—"}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  )
}